 "content": "def transform(grid):
    """Expand the inner color outward as a two-cell rectangular halo."""
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    if len(colors) < 2:
        return [row[:] for row in grid]
    # The inner color is the one occupying the smallest connected component;
    # in these nested-rectangle tasks it is also the color of the central patch.
    from collections import deque
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            components.append((len(cells), color, cells))
    # Select the smaller of the two nonzero color regions (the inset patch).
    by_color = {}
    for size, color, cells in components:
        by_color[color] = by_color.get(color, 0) + size
    inner = min(by_color, key=by_color.get)
    outer = max(by_color, key=by_color.get)
    coords = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == outer]
    r0, r1 = min(r for r, c in coords), max(r for r, c in coords)
    c0, c1 = min(c for r, c in coords), max(c for r, c in coords)
    out = [row[:] for row in grid]
    for r in range(max(0, r0-2), min(h, r1+3)):
        for c in range(max(0, c0-2), min(w, c1+3)):
            if grid[r][c] == 0:
                out[r][c] = inner
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
